import React, { useState, useEffect } from 'react';
import { useHistory, useParams } from 'react-router-dom';
import { updateCar } from '../../services/ApiCar';

export default function UpdateVoiture() {
  const history = useHistory();
  const { idCar } = useParams();
  const [carData, setCarData] = useState({
    matricule: '',
    model: '',
    marque: '',
    libelle: '',
    prix: '',
    prix_jour: '',
    couleur: '',
    disponible: false,
    voiture_image: null,
    imagePreview: ''
  });
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchCarData = async () => {
      try {
        const response = await getCarById(idCar);
        setCarData({
          ...response.data,
          imagePreview: response.data.voiture_image 
            ? `${process.env.REACT_APP_API_URL}/${response.data.voiture_image}`
            : ''
        });
        setIsLoading(false);
      } catch (error) {
        console.error('Error fetching car data:', error);
        history.push('/admin/cardvoiture');
      }
    };

    fetchCarData();
  }, [idCar, history]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCarData({ ...carData, [name]: value });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setCarData({
        ...carData,
        voiture_image: file,
        imagePreview: URL.createObjectURL(file)
      });
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!carData.matricule.trim()) newErrors.matricule = 'Matricule requis';
    if (!carData.model.trim()) newErrors.model = 'Modèle requis';
    if (!carData.marque.trim()) newErrors.marque = 'Marque requise';
    if (!carData.prix) newErrors.prix = 'Prix requis';
    if (!carData.prix_jour) newErrors.prix_jour = 'Prix par jour requis';
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    try {
      setIsLoading(true);
      const formData = new FormData();
      
      Object.keys(carData).forEach(key => {
        if (key !== 'imagePreview' && carData[key] !== null) {
          formData.append(key, carData[key]);
        }
      });

      await updateCar(formData, idCar);
      history.push('/admin/cardvoiture');
    } catch (error) {
      console.error('Update error:', error);
      alert('Erreur lors de la mise à jour');
    } finally {
      setIsLoading(false);
    }
  };

  if (isLoading) {
    return <div className="text-center py-8">Chargement en cours...</div>;
  }

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">
            Modifier la voiture {carData.matricule}
          </h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push('/admin/cardvoiture')}
          >
            Retour à la liste
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Informations du véhicule
          </h6>

          <div className="flex flex-wrap">
            {/* Matricule */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Matricule
                </label>
                <input
                  type="text"
                  name="matricule"
                  value={carData.matricule}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.matricule ? 'border border-red-500' : ''
                  }`}
                  placeholder="AA-123-BB"
                />
                {errors.matricule && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.matricule}</p>
                )}
              </div>
            </div>

            {/* Modèle */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Modèle
                </label>
                <input
                  type="text"
                  name="model"
                  value={carData.model}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.model ? 'border border-red-500' : ''
                  }`}
                  placeholder="Clio, 208, etc."
                />
                {errors.model && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.model}</p>
                )}
              </div>
            </div>

            {/* Marque */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Marque
                </label>
                <input
                  type="text"
                  name="marque"
                  value={carData.marque}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.marque ? 'border border-red-500' : ''
                  }`}
                  placeholder="Renault, Peugeot, etc."
                />
                {errors.marque && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.marque}</p>
                )}
              </div>
            </div>

            {/* Prix */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Prix (€)
                </label>
                <input
                  type="number"
                  name="prix"
                  value={carData.prix}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.prix ? 'border border-red-500' : ''
                  }`}
                  placeholder="Prix d'achat"
                />
                {errors.prix && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.prix}</p>
                )}
              </div>
            </div>

            {/* Prix par jour */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Prix par jour (€)
                </label>
                <input
                  type="number"
                  name="prix_jour"
                  value={carData.prix_jour}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.prix_jour ? 'border border-red-500' : ''
                  }`}
                  placeholder="Prix location journalière"
                />
                {errors.prix_jour && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.prix_jour}</p>
                )}
              </div>
            </div>

            {/* Image */}
            <div className="w-full px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Image du véhicule
                </label>
                {carData.imagePreview && (
                  <div className="mb-4">
                    <img 
                      src={carData.imagePreview} 
                      alt="Preview" 
                      className="h-40 object-cover rounded"
                    />
                  </div>
                )}
                <input
                  type="file"
                  name="voiture_image"
                  onChange={handleFileChange}
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
                  accept="image/*"
                />
              </div>
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              disabled={isLoading}
              className={`${
                isLoading ? 'bg-gray-500' : 'bg-green-500 hover:shadow-md'
              } text-white font-bold uppercase text-xs px-6 py-3 rounded shadow outline-none focus:outline-none mr-1 ease-linear transition-all duration-150`}
            >
              {isLoading ? 'Enregistrement...' : 'Mettre à jour'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
